entries[187611] = { ["name"] = "Nithramus", ["text"] = "Instant\nAwakens the powers of all the Savage Hallows worn by you and your allies, increasing damage dealt by [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 225 / 100]% for 15 sec.\n\nWhen this effect ends, each empowered player unleashes a blast of light that strikes all enemies within 20 yards of the initiating player's location, inflicting damage equal to ( 225 / 100)% of all damage they dealt while empowered. (2 min shared cooldown)" }
entries[187612] = { ["name"] = "Etheralus", ["text"] = "Instant\nAwakens the powers of Etheralus rings worn by you and your allies, increasing healing and absorption done by [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 225 / 100]% for 15 sec.\n\nWhen this effect ends, each empowered player unleashes a burst of energy that shields your allies, absorbing damage equal to ( 225 / 100)% of all healing done while empowered, divided evenly among the shielded players. (2 min shared cooldown)" }
entries[187613] = { ["name"] = "Sanctus", ["text"] = "Instant\nAwakens the powers of Sanctus rings worn by you and your allies, granting [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 450 / 100]% Versatility for 15 sec.\n\nFor the duration of this effect, all damage and healing received is divided evenly among empowered allies. (2 min shared cooldown)" }
